 3→/**
 4→ * Serial prompt queue — ensures prompts are processed one at a time.
 5→ */
 6→export class PromptQueue {
 7→  private queue: Array<{ text: string; attachments?: Attachment[]; resolve: () => void }> = []
 8→  private processing = false
 9→
10→  constructor(
11→    private processor: (text: string, attachments?: Attachment[]) => Promise<void>,
12→    private onError?: (err: unknown) => void,
13→  ) {}
14→
15→  async enqueue(text: string, attachments?: Attachment[]): Promise<void> {
16→    if (this.processing) {
17→      return new Promise<void>((resolve) => {
18→        this.queue.push({ text, attachments, resolve })
19→      })
20→    }
21→    await this.process(text, attachments)
22→  }
23→
24→  private async process(text: string, attachments?: Attachment[]): Promise<void> {
25→    this.processing = true
26→    try {
27→      await this.processor(text, attachments)
28→    } catch (err) {
29→      this.onError?.(err)
30→    } finally {
31→      this.processing = false
32→      this.drainNext()
33→    }
34→  }
35→
36→  private drainNext(): void {
37→    const next = this.queue.shift()
38→    if (next) {
39→      this.process(next.text, next.attachments).then(next.resolve)
40→    }
41→  }
42→
43→  clear(): void {
44→    // Resolve pending promises so callers don't hang
45→    for (const item of this.queue) {
46→      item.resolve()
47→    }
48→    this.queue = []
49→  }
50→
51→  get pending(): number {
52→    return this.queue.length
53→  }
54→
55→  get isProcessing(): boolean {
56→    return this.processing
57→  }
58→}
