 24→/** Find the nearest ancestor directory containing package.json */
 25→function findPackageRoot(startDir: string): string {
 26→  let dir = startDir;
 27→  while (dir !== path.dirname(dir)) {
 28→    if (fs.existsSync(path.join(dir, "package.json"))) {
 29→      return dir;
 30→    }
 31→    dir = path.dirname(dir);
 32→  }
 33→  return startDir;
 34→}
 35→
 36→/** Resolve an agent command to a directly executable form (avoids shell wrappers) */
 37→function resolveAgentCommand(cmd: string): { command: string; args: string[] } {
 38→  // Directories to search for node_modules: cwd AND the package's own directory
 39→  const searchRoots = [process.cwd()];
 40→  // Add the directory where this package is installed (for global installs)
 41→  // Use findPackageRoot instead of hardcoded "../.." to handle both tsc (dist/core/)
 42→  // and tsup bundle (dist/) directory structures correctly
 43→  const ownDir = findPackageRoot(import.meta.dirname);
 44→  if (ownDir !== process.cwd()) {
 45→    searchRoots.push(ownDir);
 46→  }
 47→
 48→  // 1. Check node_modules for the package's actual JS entry point
 49→  for (const root of searchRoots) {
 50→    const packageDirs = [
 51→      path.resolve(root, "node_modules", "@zed-industries", cmd, "dist", "index.js"),
 52→      path.resolve(root, "node_modules", cmd, "dist", "index.js"),
 53→    ];
 54→    for (const jsPath of packageDirs) {
 55→      if (fs.existsSync(jsPath)) {
 56→        return { command: process.execPath, args: [jsPath] };
 57→      }
 58→    }
 59→  }
 60→
 61→  // 2. Check .bin — if it's a JS file with shebang, run with node directly
 62→  for (const root of searchRoots) {
 63→    const localBin = path.resolve(root, "node_modules", ".bin", cmd);
 64→    if (fs.existsSync(localBin)) {
 65→      const content = fs.readFileSync(localBin, "utf-8");
 66→      if (content.startsWith("#!/usr/bin/env node")) {
 67→        return { command: process.execPath, args: [localBin] };
 68→      }
 69→      // Shell wrapper — try to find the target JS file
 70→      const match = content.match(/"([^"]+\.js)"/);
 71→      if (match) {
 72→        const target = path.resolve(path.dirname(localBin), match[1]);
 73→        if (fs.existsSync(target)) {
 74→          return { command: process.execPath, args: [target] };
 75→        }
 76→      }
 77→    }
 78→  }
 79→
 80→  // 3. Try resolving from PATH using which
 81→  try {
 82→    const fullPath = execFileSync("which", [cmd], { encoding: "utf-8" }).trim();
 83→    if (fullPath) {
 84→      const content = fs.readFileSync(fullPath, "utf-8");
 85→      if (content.startsWith("#!/usr/bin/env node")) {
 86→        return { command: process.execPath, args: [fullPath] };
 87→      }
 88→    }
 89→  } catch {
 90→    // which failed
 91→  }
 92→
 93→  // 4. Fallback: use command as-is
 94→  return { command: cmd, args: [] };
 95→}
