 74→export class TelegramAdapter extends ChannelAdapter<OpenACPCore> {
 75→  private bot!: Bot;
 76→  private telegramConfig: TelegramChannelConfig;
 77→  private permissionHandler!: PermissionHandler;
 78→  private assistantSession: Session | null = null;
 79→  private assistantInitializing = false;
 80→  private notificationTopicId!: number;
 81→  private assistantTopicId!: number;
 82→  private sendQueue = new TelegramSendQueue(3000);
 83→
 84→  // Extracted managers
 85→  private toolTracker!: ToolCallTracker;
 86→  private draftManager!: DraftManager;
 87→  private skillManager!: SkillCommandManager;
 88→  private fileService!: FileService;
 89→  private sessionTrackers: Map<string, ActivityTracker> = new Map();
 90→
 91→  private getOrCreateTracker(sessionId: string, threadId: number): ActivityTracker {
 92→    let tracker = this.sessionTrackers.get(sessionId);
 93→    if (!tracker) {
 94→      tracker = new ActivityTracker(
 95→        this.bot.api,
 96→        this.telegramConfig.chatId,
 97→        threadId,
 98→        this.sendQueue,
 99→      );
100→      this.sessionTrackers.set(sessionId, tracker);
101→    }
102→    return tracker;
103→  }
104→
105→  constructor(core: OpenACPCore, config: TelegramChannelConfig) {
106→    super(core, config as never);
107→    this.telegramConfig = config;
108→  }
109→
110→  async start(): Promise<void> {
111→    this.bot = new Bot(this.telegramConfig.botToken, { client: { fetch: patchedFetch } });
112→    this.fileService = this.core.fileService;
113→
114→    // Initialize extracted managers
115→    this.toolTracker = new ToolCallTracker(this.bot, this.telegramConfig.chatId, this.sendQueue);
116→    this.draftManager = new DraftManager(this.bot, this.telegramConfig.chatId, this.sendQueue);
117→    this.skillManager = new SkillCommandManager(
118→      this.bot,
119→      this.telegramConfig.chatId,
120→      this.sendQueue,
121→      this.core.sessionManager,
122→    );
123→
124→    // Global error handler — prevent unhandled errors from crashing the bot
125→    this.bot.catch((err) => {
126→      const rootCause = err.error instanceof Error ? err.error : err;
127→      log.error({ err: rootCause }, "Telegram bot error");
128→    });
129→
130→    // Auto-retry on 429 (Too Many Requests)
131→    this.bot.api.config.use(async (prev, method, payload, signal) => {
132→      const maxRetries = 3;
133→      for (let attempt = 0; attempt <= maxRetries; attempt++) {
134→        const result = await prev(method, payload, signal);
135→        if (
136→          result.ok ||
137→          (result as { error_code?: number }).error_code !== 429 ||
138→          attempt === maxRetries
139→        ) {
140→          return result;
141→        }
142→        const retryAfter =
143→          ((result as { parameters?: { retry_after?: number } }).parameters
144→            ?.retry_after ?? 5) + 1;
145→        const rateLimitedMethods = ['sendMessage', 'editMessageText', 'editMessageReplyMarkup'];
146→        if (rateLimitedMethods.includes(method)) {
147→          this.sendQueue.onRateLimited();
148→        }
149→        log.warn(
150→          { method, retryAfter, attempt: attempt + 1 },
151→          "Rate limited by Telegram, retrying",
152→        );
153→        await new Promise((r) => setTimeout(r, retryAfter * 1000));
154→      }
155→      return prev(method, payload, signal);
156→    });
157→
158→    // Ensure allowed_updates includes callback_query on every poll
159→    this.bot.api.config.use((prev, method, payload, signal) => {
160→      if (method === "getUpdates") {
161→        const p = payload as never as Record<string, unknown>;
162→        p.allowed_updates = (p.allowed_updates as string[] | undefined) ?? [
163→          "message",
164→          "callback_query",
165→        ];
166→      }
167→      return prev(method, payload, signal);
168→    });
169→
170→    // Register static commands for Telegram autocomplete
171→    await this.bot.api.setMyCommands(STATIC_COMMANDS, {
172→      scope: { type: "chat", chat_id: this.telegramConfig.chatId },
173→    });
174→
175→    // Middleware: only accept updates from configured chatId
176→    this.bot.use((ctx, next) => {
177→      const chatId = ctx.chat?.id ?? ctx.callbackQuery?.message?.chat?.id;
178→      if (chatId !== this.telegramConfig.chatId) return;
179→      return next();
180→    });
181→
182→    // Ensure system topics exist
183→    const topics = await ensureTopics(
184→      this.bot,
185→      this.telegramConfig.chatId,
186→      this.telegramConfig,
187→      async (updates) => {
188→        await this.core.configManager.save({
189→          channels: { telegram: updates },
190→        });
191→      },
192→    );
193→    this.notificationTopicId = topics.notificationTopicId;
194→    this.assistantTopicId = topics.assistantTopicId;
195→
196→    // Setup permission handler
197→    this.permissionHandler = new PermissionHandler(
198→      this.bot,
199→      this.telegramConfig.chatId,
200→      (sessionId) =>
201→        this.core.sessionManager.getSession(sessionId),
202→      (notification) => this.sendNotification(notification),
203→    );
204→
205→    // Callback registration order matters!
206→    setupDangerousModeCallbacks(this.bot, this.core as OpenACPCore);
207→    setupActionCallbacks(
208→      this.bot,
209→      this.core as OpenACPCore,
210→      this.telegramConfig.chatId,
211→      () => this.assistantSession?.id,
212→    );
213→    setupIntegrateCallbacks(this.bot, this.core as OpenACPCore);
214→    setupMenuCallbacks(
215→      this.bot,
216→      this.core as OpenACPCore,
217→      this.telegramConfig.chatId,
218→      { notificationTopicId: this.notificationTopicId, assistantTopicId: this.assistantTopicId },
219→      () => {
220→        if (!this.assistantSession) return undefined;
221→        return {
222→          topicId: this.assistantTopicId,
223→          enqueuePrompt: (p: string) => this.assistantSession!.enqueuePrompt(p),
224→        };
225→      },
226→    );
227→    setupCommands(
228→      this.bot,
229→      this.core as OpenACPCore,
230→      this.telegramConfig.chatId,
231→      {
232→        topicId: this.assistantTopicId,
233→        getSession: () => this.assistantSession,
234→        respawn: async () => {
235→          if (this.assistantSession) {
236→            await this.assistantSession.destroy();
237→            this.assistantSession = null;
238→          }
239→          const { session, ready } = await spawnAssistant(
240→            this.core as OpenACPCore,
241→            this,
242→            this.assistantTopicId,
243→          );
244→          this.assistantSession = session;
245→          this.assistantInitializing = true;
246→          ready.then(() => { this.assistantInitializing = false; });
247→        },
248→      },
249→    );
250→    this.permissionHandler.setupCallbackHandler();
251→
252→    // /handoff command
253→    this.bot.command("handoff", async (ctx) => {
254→      const threadId = ctx.message?.message_thread_id;
255→      if (!threadId) return;
256→
257→      if (threadId === this.notificationTopicId || threadId === this.assistantTopicId) {
258→        await ctx.reply("This command only works in session topics.", {
259→          message_thread_id: threadId,
260→        });
261→        return;
262→      }
263→
264→      const session = this.core.sessionManager.getSessionByThread("telegram", String(threadId));
265→      const record = session ? undefined : this.core.sessionManager.getRecordByThread("telegram", String(threadId));
266→
267→      const agentName = session?.agentName ?? record?.agentName;
268→      const agentSessionId = session?.agentSessionId ?? record?.agentSessionId;
269→
270→      if (!agentName || !agentSessionId) {
271→        await ctx.reply("No session found for this topic.", {
272→          message_thread_id: threadId,
273→        });
274→        return;
275→      }
276→
277→      const { getAgentCapabilities } = await import("../../core/agent-registry.js");
278→      const caps = getAgentCapabilities(agentName);
279→
280→      if (!caps.supportsResume || !caps.resumeCommand) {
281→        await ctx.reply("This agent does not support session transfer.", {
282→          message_thread_id: threadId,
283→        });
284→        return;
285→      }
286→
287→      const command = caps.resumeCommand(agentSessionId);
288→
289→      await ctx.reply(
290→        `Run this in your terminal to continue the session:\n\n<code>${command}</code>`,
291→        {
292→          message_thread_id: threadId,
293→          parse_mode: "HTML",
294→        },
295→      );
296→    });
297→
298→    // Setup message routing
299→    this.setupRoutes();
300→
301→    // Start bot polling
302→    this.bot.start({
303→      allowed_updates: ["message", "callback_query"],
304→      onStart: () =>
305→        log.info(
306→          { chatId: this.telegramConfig.chatId },
307→          "Telegram bot started",
308→        ),
309→    });
310→
311→    // Send welcome message
312→    try {
313→      const config = this.core.configManager.get();
314→      const agents = this.core.agentManager.getAvailableAgents();
315→      const allRecords = this.core.sessionManager.listRecords();
316→
317→      const welcomeText = buildWelcomeMessage({
318→        activeCount: allRecords.filter(r => r.status === 'active' || r.status === 'initializing').length,
319→        errorCount: allRecords.filter(r => r.status === 'error').length,
320→        totalCount: allRecords.length,
321→        agents: agents.map(a => a.name),
322→        defaultAgent: config.defaultAgent,
323→      });
324→
325→      await this.bot.api.sendMessage(this.telegramConfig.chatId, welcomeText, {
326→        message_thread_id: this.assistantTopicId,
327→        parse_mode: "HTML",
328→        reply_markup: buildMenuKeyboard(),
329→      });
330→    } catch (err) {
331→      log.warn({ err }, "Failed to send welcome message");
332→    }
333→
334→    // Spawn assistant in background
335→    try {
336→      log.info("Spawning assistant session...");
337→      const { session, ready } = await spawnAssistant(
338→        this.core as OpenACPCore,
339→        this,
340→        this.assistantTopicId,
341→      );
342→      this.assistantSession = session;
343→      this.assistantInitializing = true;
344→      log.info({ sessionId: session.id }, "Assistant session ready, system prompt running in background");
345→      ready.then(() => {
346→        this.assistantInitializing = false;
347→        log.info({ sessionId: session.id }, "Assistant ready for user messages");
348→      });
349→    } catch (err) {
350→      log.error({ err }, "Failed to spawn assistant");
351→      this.bot.api.sendMessage(
352→        this.telegramConfig.chatId,
353→        `⚠️ <b>Failed to start assistant session.</b>\n\n<code>${err instanceof Error ? err.message : String(err)}</code>`,
354→        { message_thread_id: this.assistantTopicId, parse_mode: "HTML" },
355→      ).catch(() => {});
356→    }
357→  }
