728→  async sendNotification(notification: NotificationMessage): Promise<void> {
729→    if (notification.sessionId === this.assistantSession?.id) return;
730→
731→    log.info(
732→      { sessionId: notification.sessionId, type: notification.type },
733→      "Notification sent",
734→    );
735→    if (!this.notificationTopicId) return;
736→    const emoji: Record<string, string> = {
737→      completed: "✅",
738→      error: "❌",
739→      permission: "🔐",
740→      input_required: "💬",
741→    };
742→    let text = `${emoji[notification.type] || "ℹ️"} <b>${escapeHtml(notification.sessionName || "New session")}</b>\n`;
743→    text += escapeHtml(notification.summary);
744→
745→    const deepLink = notification.deepLink ?? (() => {
746→      const session = this.core.sessionManager.getSession(notification.sessionId);
747→      const threadId = session?.threadId;
748→      if (!threadId) return undefined;
749→      const chatIdStr = String(this.telegramConfig.chatId);
750→      const numericId = chatIdStr.startsWith("-100") ? chatIdStr.slice(4) : chatIdStr.replace("-", "");
751→      return `https://t.me/c/${numericId}/${threadId}`;
752→    })();
753→
754→    if (deepLink) {
755→      text += `\n\n<a href="${deepLink}">→ Go to topic</a>`;
756→    }
757→    await this.sendQueue.enqueue(() =>
758→      this.bot.api.sendMessage(this.telegramConfig.chatId, text, {
759→        message_thread_id: this.notificationTopicId,
760→        parse_mode: "HTML",
761→        disable_notification: false,
762→      }),
763→    );
