831→  private async handleIncomingMedia(
832→    threadId: number,
833→    userId: number,
834→    fileId: string,
835→    fileName: string,
836→    mimeType: string,
837→    caption?: string,
838→    convertOggToWav?: boolean,
839→  ): Promise<void> {
840→    const downloaded = await this.downloadTelegramFile(fileId);
841→    if (!downloaded) return;
842→
843→    let buffer = downloaded.buffer;
844→    if (convertOggToWav) {
845→      try {
