847→      } catch (err) {
848→        log.warn({ err }, "OGG→WAV conversion failed, saving original OGG");
849→        fileName = "voice.ogg";
850→        mimeType = "audio/ogg";
851→      }
852→    }
853→
854→    const sessionId = this.resolveSessionId(threadId) || "unknown";
855→    const att = await this.fileService.saveFile(sessionId, fileName, buffer, mimeType);
856→
857→    const text = caption || `[${att.type === "image" ? "Photo" : att.type === "audio" ? "Audio" : "File"}: ${att.fileName}]`;
858→
859→    // Assistant topic
860→    if (threadId === this.assistantTopicId) {
861→      if (this.assistantSession) {
862→        await this.assistantSession.enqueuePrompt(text, [att]);
863→      }
864→      return;
865→    }
866→
867→    // Session topic
868→    const sid = this.resolveSessionId(threadId);
869→    if (sid) await this.draftManager.finalize(sid, this.assistantSession?.id);
870→    this.core
871→      .handleMessage({
872→        channelId: "telegram",
873→        threadId: String(threadId),
874→        userId: String(userId),
875→        text,
876→        attachments: [att],
877→      })
878→      .catch((err) => log.error({ err }, "handleMessage error"));
879→  }
