  8→export class MessageTransformer {
  9→  constructor(private tunnelService?: TunnelService) {}
 10→
 11→  transform(
 12→    event: AgentEvent,
 13→    sessionContext?: { id: string; workingDirectory: string },
 14→  ): OutgoingMessage {
 15→    switch (event.type) {
 16→      case "text":
 17→        return { type: "text", text: event.content };
 18→      case "thought":
 19→        return { type: "thought", text: event.content };
 20→      case "tool_call": {
 21→        const metadata: Record<string, unknown> = {
 22→          id: event.id,
 23→          name: event.name,
 24→          kind: event.kind,
 25→          status: event.status,
 26→          content: event.content,
 27→          locations: event.locations,
 28→        };
 29→        this.enrichWithViewerLinks(event, metadata, sessionContext);
 30→        return { type: "tool_call", text: event.name, metadata };
 31→      }
 32→      case "tool_update": {
 33→        const metadata: Record<string, unknown> = {
 34→          id: event.id,
 35→          name: event.name,
 36→          kind: event.kind,
 37→          status: event.status,
 38→          content: event.content,
 39→        };
 40→        this.enrichWithViewerLinks(event, metadata, sessionContext);
 41→        return { type: "tool_update", text: "", metadata };
 42→      }
 43→      case "plan":
 44→        return {
 45→          type: "plan",
 46→          text: "",
 47→          metadata: { entries: event.entries },
 48→        };
 49→      case "usage":
 50→        return {
 51→          type: "usage",
 52→          text: "",
 53→          metadata: {
 54→            tokensUsed: event.tokensUsed,
 55→            contextSize: event.contextSize,
 56→            cost: event.cost,
 57→          },
 58→        };
 59→      case "session_end":
 60→        return { type: "session_end", text: `Done (${event.reason})` };
 61→      case "error":
 62→        return { type: "error", text: event.message };
 63→      default:
 64→        return { type: "text", text: "" };
 65→    }
 66→  }
 67→
 68→  private enrichWithViewerLinks(
 69→    event: AgentEvent & { type: "tool_call" | "tool_update" },
 70→    metadata: Record<string, unknown>,
 71→    sessionContext?: { id: string; workingDirectory: string },
 72→  ): void {
 73→    if (!this.tunnelService || !sessionContext) return;
 74→
 75→    const name = "name" in event ? event.name || "" : "";
 76→    const kind = "kind" in event ? event.kind : undefined;
 77→
 78→    log.debug(
 79→      { name, kind, status: event.status, hasContent: !!event.content },
 80→      "enrichWithViewerLinks: inspecting event",
 81→    );
 82→
 83→    const fileInfo = extractFileInfo(
 84→      name,
 85→      kind,
 86→      event.content,
 87→      event.rawInput,
 88→      event.meta,
 89→    );
 90→    if (!fileInfo) return;
 91→
 92→    log.info(
 93→      {
 94→        name,
 95→        kind,
 96→        filePath: fileInfo.filePath,
 97→        hasOldContent: !!fileInfo.oldContent,
 98→      },
 99→      "enrichWithViewerLinks: extracted file info",
100→    );
101→
102→    const store = this.tunnelService.getStore();
103→    const viewerLinks: Record<string, string> = {};
104→
105→    // For edits/writes with diff data (oldText + newText)
106→    if (fileInfo.oldContent) {
107→      const id = store.storeDiff(
108→        sessionContext.id,
109→        fileInfo.filePath,
110→        fileInfo.oldContent,
111→        fileInfo.content,
112→        sessionContext.workingDirectory,
113→      );
114→      if (id) viewerLinks.diff = this.tunnelService.diffUrl(id);
115→    }
116→
117→    // Always store as file view (new file creation or read)
118→    const id = store.storeFile(
119→      sessionContext.id,
120→      fileInfo.filePath,
121→      fileInfo.content,
122→      sessionContext.workingDirectory,
123→    );
124→    if (id) viewerLinks.file = this.tunnelService.fileUrl(id);
125→
126→    if (Object.keys(viewerLinks).length > 0) {
127→      metadata.viewerLinks = viewerLinks;
128→      metadata.viewerFilePath = fileInfo.filePath;
129→    }
130→  }
131→}
