   216→      this.core as OpenACPCore,
   217→      this.telegramConfig.chatId,
   218→      { notificationTopicId: this.notificationTopicId, assistantTopicId: this.assistantTopicId },
   219→      () => {
   220→        if (!this.assistantSession) return undefined;
   221→        return {
   222→          topicId: this.assistantTopicId,
   223→          enqueuePrompt: (p: string) => this.assistantSession!.enqueuePrompt(p),
   224→        };
   225→      },
   226→    );
   227→    setupCommands(
   228→      this.bot,
   229→      this.core as OpenACPCore,
   230→      this.telegramConfig.chatId,
   231→      {
   232→        topicId: this.assistantTopicId,
   233→        getSession: () => this.assistantSession,
   234→        respawn: async () => {
   235→          if (this.assistantSession) {
   236→            await this.assistantSession.destroy();
   237→            this.assistantSession = null;
   238→          }
   239→          const { session, ready } = await spawnAssistant(
   240→            this.core as OpenACPCore,
   241→            this,
   242→            this.assistantTopicId,
   243→          );
   244→          this.assistantSession = session;
   245→          this.assistantInitializing = true;
   246→          ready.then(() => { this.assistantInitializing = false; });
   247→        },
   248→      },
   249→    );
   250→    this.permissionHandler.setupCallbackHandler();
   251→
   252→    // /handoff command
   253→    this.bot.command("handoff", async (ctx) => {
   254→      const threadId = ctx.message?.message_thread_id;
   255→      if (!threadId) return;
   256→
   257→      if (threadId === this.notificationTopicId || threadId === this.assistantTopicId) {
   258→        await ctx.reply("This command only works in session topics.", {
   259→          message_thread_id: threadId,
   260→        });
   261→        return;
   262→      }
   263→
   264→      const session = this.core.sessionManager.getSessionByThread("telegram", String(threadId));
   265→      const record = session ? undefined : this.core.sessionManager.getRecordByThread("telegram", String(threadId));
   266→
   267→      const agentName = session?.agentName ?? record?.agentName;
   268→      const agentSessionId = session?.agentSessionId ?? record?.agentSessionId;
   269→
   270→      if (!agentName || !agentSessionId) {
   271→        await ctx.reply("No session found for this topic.", {
   272→          message_thread_id: threadId,
   273→        });
   274→        return;
   275→      }
   276→
   277→      const { getAgentCapabilities } = await import("../../core/agent-registry.js");
   278→      const caps = getAgentCapabilities(agentName);
   279→
   280→      if (!caps.supportsResume || !caps.resumeCommand) {
   281→        await ctx.reply("This agent does not support session transfer.", {
   282→          message_thread_id: threadId,
   283→        });
   284→        return;
   285→      }
   286→
   287→      const command = caps.resumeCommand(agentSessionId);
   288→
   289→      await ctx.reply(
   290→        `Run this in your terminal to continue the session:\n\n<code>${command}</code>`,
   291→        {
   292→          message_thread_id: threadId,
   293→          parse_mode: "HTML",
   294→        },
   295→      );
   296→    });
   297→
   298→    // Setup message routing
   299→    this.setupRoutes();
   300→
   301→    // Start bot polling
   302→    this.bot.start({
   303→      allowed_updates: ["message", "callback_query"],
   304→      onStart: () =>
   305→        log.info(
   306→          { chatId: this.telegramConfig.chatId },
   307→          "Telegram bot started",
   308→        ),
   309→    });
   310→
   311→    // Send welcome message
   312→    try {
   313→      const config = this.core.configManager.get();
   314→      const agents = this.core.agentManager.getAvailableAgents();
   315→      const allRecords = this.core.sessionManager.listRecords();
   316→
   317→      const welcomeText = buildWelcomeMessage({
   318→        activeCount: allRecords.filter(r => r.status === 'active' || r.status === 'initializing').length,
   319→        errorCount: allRecords.filter(r => r.status === 'error').length,
   320→        totalCount: allRecords.length,
   321→        agents: agents.map(a => a.name),
   322→        defaultAgent: config.defaultAgent,
   323→      });
   324→
   325→      await this.bot.api.sendMessage(this.telegramConfig.chatId, welcomeText, {
   326→        message_thread_id: this.assistantTopicId,
   327→        parse_mode: "HTML",
   328→        reply_markup: buildMenuKeyboard(),
   329→      });
   330→    } catch (err) {
   331→      log.warn({ err }, "Failed to send welcome message");
   332→    }
   333→
   334→    // Spawn assistant in background
   335→    try {
   336→      log.info("Spawning assistant session...");
   337→      const { session, ready } = await spawnAssistant(
   338→        this.core as OpenACPCore,
   339→        this,
   340→        this.assistantTopicId,
   341→      );
   342→      this.assistantSession = session;
   343→      this.assistantInitializing = true;
   344→      log.info({ sessionId: session.id }, "Assistant session ready, system prompt running in background");
   345→      ready.then(() => {
   346→        this.assistantInitializing = false;
   347→        log.info({ sessionId: session.id }, "Assistant ready for user messages");
   348→      });
   349→    } catch (err) {
   350→      log.error({ err }, "Failed to spawn assistant");
   351→      this.bot.api.sendMessage(
   352→        this.telegramConfig.chatId,
   353→        `⚠️ <b>Failed to start assistant session.</b>\n\n<code>${err instanceof Error ? err.message : String(err)}</code>`,
   354→        { message_thread_id: this.assistantTopicId, parse_mode: "HTML" },
   355→      ).catch(() => {});
   356→    }
   357→  }
