   104→  // --- Message Routing ---
   105→
   106→  async handleMessage(message: IncomingMessage): Promise<void> {
   107→    const config = this.configManager.get();
   108→    log.debug(
   109→      {
   110→        channelId: message.channelId,
   111→        threadId: message.threadId,
   112→        userId: message.userId,
   113→      },
   114→      "Incoming message",
   115→    );
   116→
   117→    // Security: check allowed user IDs
   118→    // Both Telegram (numeric) and Discord (snowflake string) IDs are compared as strings
   119→    if (config.security.allowedUserIds.length > 0) {
   120→      const userId = String(message.userId)
   121→      if (!config.security.allowedUserIds.includes(userId)) {
   122→        log.warn(
   123→          { userId },
   124→          "Rejected message from unauthorized user",
   125→        );
   126→        return;
   127→      }
   128→    }
   129→
   130→    // Check concurrent session limit
   131→    const activeSessions = this.sessionManager
   132→      .listSessions()
   133→      .filter((s) => s.status === "active" || s.status === "initializing");
   134→    if (activeSessions.length >= config.security.maxConcurrentSessions) {
   135→      log.warn(
   136→        {
   137→          userId: message.userId,
   138→          currentCount: activeSessions.length,
   139→          max: config.security.maxConcurrentSessions,
   140→        },
   141→        "Session limit reached",
   142→      );
   143→      const adapter = this.adapters.get(message.channelId);
   144→      if (adapter) {
   145→        await adapter.sendMessage(message.threadId, {
   146→          type: "error",
   147→          text: `⚠️ Session limit reached (${config.security.maxConcurrentSessions}). Please cancel existing sessions with /cancel before starting new ones.`,
   148→        });
   149→      }
   150→      return;
   151→    }
   152→
   153→    // Find session by thread
   154→    let session = this.sessionManager.getSessionByThread(
   155→      message.channelId,
   156→      message.threadId,
   157→    );
   158→
   159→    // Lazy resume: try to restore session from store
   160→    if (!session) {
   161→      session = (await this.lazyResume(message)) ?? undefined;
   162→    }
   163→
   164→    if (!session) {
   165→      log.warn(
   166→        { channelId: message.channelId, threadId: message.threadId },
   167→        "No session found for thread (in-memory miss + lazy resume returned null)",
   168→      );
   169→      return;
   170→    }
   171→
   172→    // Update activity timestamp
   173→    this.sessionManager.patchRecord(session.id, { lastActiveAt: new Date().toISOString() });
   174→
   175→    // Forward to session
   176→    await session.enqueuePrompt(message.text, message.attachments);
   177→  }
