   105→  constructor(core: OpenACPCore, config: TelegramChannelConfig) {
   106→    super(core, config as never);
   107→    this.telegramConfig = config;
   108→  }
   109→
   110→  async start(): Promise<void> {
   111→    this.bot = new Bot(this.telegramConfig.botToken, { client: { fetch: patchedFetch } });
   112→    this.fileService = this.core.fileService;
   113→
   114→    // Initialize extracted managers
   115→    this.toolTracker = new ToolCallTracker(this.bot, this.telegramConfig.chatId, this.sendQueue);
   116→    this.draftManager = new DraftManager(this.bot, this.telegramConfig.chatId, this.sendQueue);
   117→    this.skillManager = new SkillCommandManager(
   118→      this.bot,
   119→      this.telegramConfig.chatId,
   120→      this.sendQueue,
   121→      this.core.sessionManager,
   122→    );
   123→
   124→    // Global error handler — prevent unhandled errors from crashing the bot
   125→    this.bot.catch((err) => {
   126→      const rootCause = err.error instanceof Error ? err.error : err;
   127→      log.error({ err: rootCause }, "Telegram bot error");
   128→    });
   129→
   130→    // Auto-retry on 429 (Too Many Requests)
   131→    this.bot.api.config.use(async (prev, method, payload, signal) => {
   132→      const maxRetries = 3;
   133→      for (let attempt = 0; attempt <= maxRetries; attempt++) {
   134→        const result = await prev(method, payload, signal);
   135→        if (
   136→          result.ok ||
   137→          (result as { error_code?: number }).error_code !== 429 ||
   138→          attempt === maxRetries
   139→        ) {
   140→          return result;
   141→        }
   142→        const retryAfter =
   143→          ((result as { parameters?: { retry_after?: number } }).parameters
   144→            ?.retry_after ?? 5) + 1;
   145→        const rateLimitedMethods = ['sendMessage', 'editMessageText', 'editMessageReplyMarkup'];
   146→        if (rateLimitedMethods.includes(method)) {
   147→          this.sendQueue.onRateLimited();
   148→        }
   149→        log.warn(
   150→          { method, retryAfter, attempt: attempt + 1 },
   151→          "Rate limited by Telegram, retrying",
   152→        );
   153→        await new Promise((r) => setTimeout(r, retryAfter * 1000));
   154→      }
   155→      return prev(method, payload, signal);
   156→    });
   157→
   158→    // Ensure allowed_updates includes callback_query on every poll
   159→    this.bot.api.config.use((prev, method, payload, signal) => {
   160→      if (method === "getUpdates") {
   161→        const p = payload as never as Record<string, unknown>;
   162→        p.allowed_updates = (p.allowed_updates as string[] | undefined) ?? [
   163→          "message",
   164→          "callback_query",
   165→        ];
   166→      }
   167→      return prev(method, payload, signal);
   168→    });
   169→
   170→    // Register static commands for Telegram autocomplete
   171→    await this.bot.api.setMyCommands(STATIC_COMMANDS, {
   172→      scope: { type: "chat", chat_id: this.telegramConfig.chatId },
   173→    });
   174→
   175→    // Middleware: only accept updates from configured chatId
   176→    this.bot.use((ctx, next) => {
   177→      const chatId = ctx.chat?.id ?? ctx.callbackQuery?.message?.chat?.id;
   178→      if (chatId !== this.telegramConfig.chatId) return;
   179→      return next();
   180→    });
   181→
   182→    // Ensure system topics exist
   183→    const topics = await ensureTopics(
   184→      this.bot,
   185→      this.telegramConfig.chatId,
   186→      this.telegramConfig,
   187→      async (updates) => {
   188→        await this.core.configManager.save({
   189→          channels: { telegram: updates },
   190→        });
   191→      },
   192→    );
   193→    this.notificationTopicId = topics.notificationTopicId;
   194→    this.assistantTopicId = topics.assistantTopicId;
   195→
   196→    // Setup permission handler
   197→    this.permissionHandler = new PermissionHandler(
   198→      this.bot,
   199→      this.telegramConfig.chatId,
   200→      (sessionId) =>
   201→        this.core.sessionManager.getSession(sessionId),
   202→      (notification) => this.sendNotification(notification),
   203→    );
   204→
   205→    // Callback registration order matters!
   206→    setupDangerousModeCallbacks(this.bot, this.core as OpenACPCore);
   207→    setupActionCallbacks(
   208→      this.bot,
   209→      this.core as OpenACPCore,
   210→      this.telegramConfig.chatId,
   211→      () => this.assistantSession?.id,
   212→    );
   213→    setupIntegrateCallbacks(this.bot, this.core as OpenACPCore);
   214→    setupMenuCallbacks(
   215→      this.bot,
   216→      this.core as OpenACPCore,
   217→      this.telegramConfig.chatId,
   218→      { notificationTopicId: this.notificationTopicId, assistantTopicId: this.assistantTopicId },
   219→      () => {
   220→        if (!this.assistantSession) return undefined;
   221→        return {
   222→          topicId: this.assistantTopicId,
