   367→  private setupRoutes(): void {
   368→    this.bot.on("message:text", async (ctx) => {
   369→      const threadId = ctx.message.message_thread_id;
   370→
   371→      // Check for pending workspace input from interactive /new flow
   372→      if (await handlePendingWorkspaceInput(ctx, this.core, this.telegramConfig.chatId, this.assistantTopicId)) {
   373→        return;
   374→      }
   375→
   376→      // General topic or no thread → redirect to assistant
   377→      if (!threadId) {
   378→        const html = redirectToAssistant(
   379→          this.telegramConfig.chatId,
   380→          this.assistantTopicId,
   381→        );
   382→        await ctx.reply(html, { parse_mode: "HTML" });
   383→        return;
   384→      }
   385→
   386→      // Notification topic → ignore
   387→      if (threadId === this.notificationTopicId) return;
   388→
   389→      // Assistant topic → forward to assistant session
   390→      if (threadId === this.assistantTopicId) {
   391→        if (!this.assistantSession) {
   392→          await ctx.reply("⚠️ Assistant is not available yet. Please try again shortly.", { parse_mode: "HTML" });
   393→          return;
   394→        }
   395→        await this.draftManager.finalize(this.assistantSession.id, this.assistantSession.id);
   396→        ctx.replyWithChatAction("typing").catch(() => {});
   397→        handleAssistantMessage(this.assistantSession, ctx.message.text).catch(
   398→          (err) => log.error({ err }, "Assistant error"),
   399→        );
   400→        return;
   401→      }
   402→
   403→      // Session topic → forward to core
   404→      const sessionId = this.core.sessionManager.getSessionByThread("telegram", String(threadId))?.id;
   405→      if (sessionId) await this.draftManager.finalize(sessionId, this.assistantSession?.id);
   406→      if (sessionId) {
   407→        const tracker = this.sessionTrackers.get(sessionId);
   408→        if (tracker) await tracker.onNewPrompt();
   409→      }
   410→      ctx.replyWithChatAction("typing").catch(() => {});
   411→      this.core
   412→        .handleMessage({
   413→          channelId: "telegram",
   414→          threadId: String(threadId),
   415→          userId: String(ctx.from.id),
   416→          text: ctx.message.text,
   417→        })
   418→        .catch((err) => log.error({ err }, "handleMessage error"));
   419→    });
   420→
   421→    // --- Incoming media handlers ---
