   518→  async prompt(text: string, attachments?: Attachment[]): Promise<PromptResponse> {
   519→    const contentBlocks: Array<Record<string, unknown>> = [{ type: "text", text }];
   520→
   521→    for (const att of attachments ?? []) {
   522→      const tooLarge = att.size > 10 * 1024 * 1024; // 10MB base64 guard
   523→
   524→      if (att.type === "image" && this.promptCapabilities?.image && !tooLarge) {
   525→        const data = await fs.promises.readFile(att.filePath);
   526→        contentBlocks.push({ type: "image", data: data.toString("base64"), mimeType: att.mimeType });
   527→      } else if (att.type === "audio" && this.promptCapabilities?.audio && !tooLarge) {
   528→        const data = await fs.promises.readFile(att.filePath);
   529→        contentBlocks.push({ type: "audio", data: data.toString("base64"), mimeType: att.mimeType });
   530→      } else {
   531→        // Fallback: append file path to text so agent can read from disk
   532→        if ((att.type === "image" || att.type === "audio") && !tooLarge) {
   533→          log.debug(
   534→            { type: att.type, capabilities: this.promptCapabilities ?? {} },
   535→            "Agent does not support %s content, falling back to file path",
   536→            att.type,
   537→          );
   538→        }
   539→        (contentBlocks[0] as { text: string }).text += `\n\n[Attached file: ${att.filePath}]`;
   540→      }
   541→    }
   542→
   543→    return this.connection.prompt({
   544→      sessionId: this.sessionId,
   545→      prompt: contentBlocks as any,
   546→    });
   547→  }
