 48→/**
 49→ * Wraps native fetch to work around grammY's polyfilled AbortController.
 50→ * grammY uses abort-controller polyfill whose AbortSignal fails instanceof
 51→ * checks in Node 24+ native fetch. This wrapper re-creates a native
 52→ * AbortSignal from the polyfilled one before passing it to fetch.
 53→ */
 54→function patchedFetch(
 55→  input: RequestInfo | URL,
 56→  init?: RequestInit,
 57→): Promise<Response> {
 58→  if (init?.signal && !(init.signal instanceof AbortSignal)) {
 59→    const nativeController = new AbortController();
 60→    const polyfillSignal = init.signal as unknown as {
 61→      aborted: boolean;
 62→      addEventListener: (event: string, fn: () => void) => void;
 63→    };
 64→    if (polyfillSignal.aborted) {
 65→      nativeController.abort();
 66→    } else {
 67→      polyfillSignal.addEventListener("abort", () => nativeController.abort());
 68→    }
 69→    init = { ...init, signal: nativeController.signal };
 70→  }
 71→  return fetch(input, init);
 72→}
