393→          return;
394→        }
395→        await this.draftManager.finalize(this.assistantSession.id, this.assistantSession.id);
396→        ctx.replyWithChatAction("typing").catch(() => {});
397→        handleAssistantMessage(this.assistantSession, ctx.message.text).catch(
398→          (err) => log.error({ err }, "Assistant error"),
399→        );
400→        return;
401→      }
402→
403→      // Session topic → forward to core
404→      const sessionId = this.core.sessionManager.getSessionByThread("telegram", String(threadId))?.id;
405→      if (sessionId) await this.draftManager.finalize(sessionId, this.assistantSession?.id);
406→      if (sessionId) {
407→        const tracker = this.sessionTrackers.get(sessionId);
