695→  async sendPermissionRequest(
696→    sessionId: string,
697→    request: PermissionRequest,
698→  ): Promise<void> {
699→    log.info({ sessionId, requestId: request.id }, "Permission request sent");
700→    const session = this.core.sessionManager.getSession(sessionId);
701→    if (!session) return;
702→
703→    // Auto-approve openacp CLI commands
704→    if (request.description.includes("openacp")) {
705→      const allowOption = request.options.find((o) => o.isAllow);
706→      if (allowOption && session.permissionGate.requestId === request.id) {
707→        log.info({ sessionId, requestId: request.id }, "Auto-approving openacp command");
708→        session.permissionGate.resolve(allowOption.id);
709→      }
710→      return;
711→    }
712→
713→    // Dangerous mode: auto-approve
714→    if (session.dangerousMode) {
715→      const allowOption = request.options.find((o) => o.isAllow);
716→      if (allowOption && session.permissionGate.requestId === request.id) {
717→        log.info({ sessionId, requestId: request.id, optionId: allowOption.id }, "Dangerous mode: auto-approving permission");
718→        session.permissionGate.resolve(allowOption.id);
719→      }
720→      return;
721→    }
722→
723→    await this.sendQueue.enqueue(() =>
724→      this.permissionHandler.sendPermissionRequest(session, request),
725→    );
726→  }
